import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const u=JSON.parse('{"title":"巽下离上 鼎：","description":"京氏易传 - 巽下离上 鼎：","frontmatter":{"title":"巽下离上 鼎：","description":"京氏易传 - 巽下离上 鼎："},"headers":[],"relativePath":"zh/classics/jingshi/052.md","filePath":"zh/classics/jingshi/052.md"}'),i={name:"zh/classics/jingshi/052.md"};function r(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"巽下离上-鼎",tabindex:"-1"},[l("巽下离上 鼎： "),e("a",{class:"header-anchor",href:"#巽下离上-鼎","aria-label":"Permalink to “巽下离上 鼎：”"},"​")],-1),e("p",null,"木能巽火，故鼎之象。亨饪见新，供祭明矣。《易》曰：“鼎取新”。（虎易注：此句出于杂卦传，原句为“鼎，取新也”。）【木见火中，发火木相资，象鼎之兆。下穴为足，中虚见纳，饪熟之义明矣。凡饪熟，享祀为先。故曰供祭明矣。变生也。】阴阳得应，居中履顺，三公之义，继于君也。【九三成鼎之德，六五委任得贤臣，假之位，以斯明矣。】阴穴见火，顺于上也；中虚见纳，受辛于内也。金玉之铉在乎阳，飨新亨饪在乎阴。与巽为飞伏。【辛亥水，己丑土。】九二立大夫为世，六五居尊见应。",-1),e("p",null,"建始庚戌至乙卯【寒露，春分。】积算起乙卯至甲寅，周而复始。分土木入离巽。【分土木二象入离巽，配鼎卦。】",-1),e("p",null,"五星从位起镇星，【土星入火宫。】奎宿从位降辛亥水，【二十八宿，分奎宿入鼎卦九二辛亥位上。】分气候三十六。【起宫数三十六宫配卦算吉凶。】",-1),e("p",null,"火居木上，二气交合，阴阳巽顺，器具形成。金玉坚刚，配象阴阳，升降六位，递相迁次，",-1),e("p",null,"九三适变，以阳入阴，见乎坎险。【鼎九三爻之义，阴成坎卦，外象，内坎外离，二气不交，见未济卦。】降入水火未济卦。（虎易注：水火未济，当为火水未济之误。）",-1)])])}const _=s(i,[["render",r]]);export{u as __pageData,_ as default};
